results.css:
.card .pri:is(:not(:empty)) {
  color: rgb(194, 65, 12) !important;
  background: rgb(255, 237, 213) !important;
}

.card:has(.pri:not(:empty)) {
  border-color: rgb(251, 146, 60) !important;
}

article.card[data-morse-high] {
  border-color: #f97316;
  background: #fff7ed;
  box-shadow: inset 3px 0 0 #f97316;
}
article.card[data-morse-high] .pri {
  color: #c2410c;
  background: #ffedd5;
}

results.js:
morse.watch('article.card > span.pri', (el) => {
  const card = el.closest('article.card');
  if (!card) return;
  if (el.textContent.trim() === 'High') {
    card.setAttribute('data-morse-high', '');
  } else {
    card.removeAttribute('data-morse-high');
  }
}, { live: true });

const GRID = '#__next > div:nth-of-type(2) > main > div:nth-of-type(2)';
const priceOf = c => {
  const m = /\$([\d,]+(?:\.\d+)?)/.exec(c.textContent);
  return m ? parseFloat(m[1].replace(/,/g, '')) : Infinity;
};
morse.watch('#__next > div:nth-of-type(2) > main > div:nth-of-type(1)', hdr => {
  const btn = morse.el('button', {
    type: 'button',
    text: 'Sort by price: low to high',
    style: 'margin-left:auto;font:inherit;font-size:13px;color:inherit;background:none;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:.8'
  });
  morse.on(btn, 'click', () => {
    const grid = morse.$(GRID);
    if (!grid) return;
    const cards = [...grid.children];
    cards.sort((a, b) => priceOf(a) - priceOf(b));
    cards.forEach(c => grid.appendChild(c));
  });
  hdr.appendChild(btn);
});

const GRID = "#__next > div:nth-of-type(2) > main > div:nth-of-type(2)";
const priceOf = c => {
  const m = c.textContent.match(/\$(\d+(?:\.\d+)?)/);
  return m ? parseFloat(m[1]) : Infinity;
};

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  const btn = morse.el("button", {
    text: "Sort: price, low to high",
    style: "margin-left:auto; font:inherit; font-size:14px; padding:4px 10px; border:1px solid rgb(214,211,209); border-radius:6px; background:transparent; color:inherit; cursor:pointer;",
    on: {
      click: () => {
        const grid = morse.$(GRID);
        if (!grid) return;
        [...grid.children]
          .sort((a, b) => priceOf(a) - priceOf(b))
          .forEach(c => grid.appendChild(c));
      }
    }
  });
  bar.appendChild(btn);
});

