  font-size: 14px;
  padding: 6px 14px;
  margin: 8px 0 12px;
  border: 1px solid currentColor;
  border-radius: 999px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.hearth-all-off:hover { opacity: 0.7; }

results.js:
morse.watch("#where", el => {
  const btn = morse.el("button", {
    class: "hearth-all-off",
    type: "button",
    text: "All devices off",
    on: {
      click: () => {
        const targets = morse.$$("device-card >>> button[aria-label$=': on']:not([disabled])");
        targets.forEach(b => b.click());
        morse.toast(`Turned off ${targets.length} device(s)`);
      }
    }
  });
  el.after(btn);
});
